import * as M from './model.js';
import {knownIds,permitted} from './community-life.js';
import * as A from './academic-year.js';
export const HEALTH_TOPICS=['인플루엔자','코로나19','수두','유행성이하선염','수족구병','유행성각결막염','노로바이러스 감염증','백일해'];
export const KINDS={health:'건강 이상·보건 지원',order:'생활질서 지도',disruption:'반복 수업방해 지원',violence:'학교폭력 관련 보호 요청',rights:'교육활동 보호 요청',welfare:'학생맞춤·가정 지원',device:'디지털기기 사용 지도'};
export const STEPS={health:['관찰과 보호','보건 담당자 연결','확인된 안내·출결·가정 연락','복귀 확인·학습 연결'],order:['관찰·이유 듣기','약속과 대안 정하기','실천 확인·후속 기록'],disruption:['관찰·도움 확인','첫 지도와 대안','반복 상황·학습 방해 확인','학교 책임자·담당자 협의','개별 학습 지원','복귀·후속 점검'],violence:['안전 확보·보호 요청','학교 담당자에게 사실 전달','공식 처리·지원 안내 확인','보호·회복과 후속 점검'],rights:['안전과 연락 창구 확인','관리자·대응 담당자 지원 요청','공식 절차·지원 안내 확인','회복·업무 조정 점검'],welfare:['학생의 필요 듣기','전문 담당자·학교 지원 연결','가정과 최소 정보 협의','지원 결과와 다음 확인'],device:['사용 맥락·보조기기 확인','수업용 방법·보관 협의','반환·지원과 후속 확인']};
export const TRAITS=[['긴 설명을 나누어 안내하면 도움이 됨','ADHD 관련 지원 · 보호자 확인'],['접근 가능한 동선과 자료가 필요함','장애 관련 지원 · 보호자 확인'],['익숙한 언어와 안내 그림이 도움이 됨','다문화 가정 · 보호자 확인'],['학교와 지역에 익숙해질 시간이 필요함','이주·북한이탈 배경 · 공유 동의 범위 확인'],['식품별 대체 제공을 확인함','식품 알레르기 · 보건교사 확인'],['심화 탐구 선택 기회가 도움이 됨','영재교육 참여 · 담당자 확인'],['운동 활동에서 희망과 휴식을 함께 확인함','체육 관심·특기'],['다양한 재료로 표현하는 것을 좋아함','예술 관심·특기']];
export function data(s){const d=s.support??={schema:1,cases:[],placements:{},documents:[],attendanceChanges:[],handoffs:[],seen:{},rules:{familyLeadDays:3,familyReportDays:5,absenceDays:5,homeStudy:false}};if(!d.legacyMigrated){for(const old of s.forms||[]){d.documents.push({id:'legacy-'+old.id,studentId:old.studentId,kind:old.kind.includes('체험')?'family':'absence',from:old.day,to:old.day,detail:old.detail,evidence:old.detail,absenceType:'질병결석',channels:['이전 저장'],stage:old.status==='접수'?'received':old.status.includes('보완')?'revision':'closed',date:old.date,history:[{action:'이전 기록 보존',text:old.status,date:old.date}]});}d.legacyMigrated=true;}for(const [i,st] of s.students.entries())st.supportInfo??={needs:i%3===0?TRAITS[Math.floor(i/3)%TRAITS.length][0]:'학생이 선호하는 참여 방법을 살펴보는 중',detail:i%3===0?TRAITS[Math.floor(i/3)%TRAITS.length][1]:'별도 공유된 민감 정보 없음',confirmed:i%3===0,scope:'담임·필요한 지원 담당자',recorded:M.stamp(s)};return d;}
export function available(s,id){const p=data(s).placements[id];return !p||p.status==='returned'||p.room===s.room;}
export function open(s,studentId,kind,observation){const d=data(s);if(!s.students.some(x=>x.id===studentId)||!KINDS[kind])return false;if(String(observation).trim().length<8)return {error:'관찰한 사실과 학생의 말을 구체적으로 적어 주세요.'};if(d.cases.some(c=>c.studentId===studentId&&c.kind===kind&&!c.closed))return {error:'같은 학생의 진행 중인 지원 기록을 이어서 확인해 주세요.'};const c={id:'support-'+s.academic.year+'-'+d.cases.length,studentId,kind,step:0,closed:false,day:s.day,date:M.stamp(s),observation:String(observation).slice(0,1000),history:[],response:null,health:null,assignee:null};d.cases.push(c);return {ok:true,id:c.id};}
export function act(s,id,choice,note){const d=data(s),c=d.cases.find(x=>x.id===id);if(!c||c.closed||![0,1].includes(choice))return false;if(String(note).trim().length<5)return {error:'이번에 확인한 사실·지원 방법·다음 점검을 적어 주세요.'};if(s.academic.phase==='preparation')return {error:'학생이 등교한 뒤 관찰과 지원을 진행해 주세요.'};if(s.staffWork?.away)return {error:'출장 중에는 담당자에게 연락하고 복귀 후 직접 지원을 진행합니다.'};const st=s.students.find(x=>x.id===c.studentId),steps=STEPS[c.kind],text=String(note).trim().slice(0,1000);
 if(c.kind==='disruption'&&c.step===2&&choice===1){c.response='협의 후 수업에 참여';c.history.push({step:c.step,text,date:M.stamp(s),choice});c.step=5;return {ok:true};}
 if(c.kind==='disruption'&&c.step===3){if(choice===1){c.response='관리자와 교실 안 지원 강화';c.step=5;return {ok:true};}if(!/학습|방해|반복|안전/.test(c.observation+' '+text))return {error:'단순한 거절만으로 분리하지 않습니다. 반복 상황·학습권 영향과 학교의 지원 근거를 확인해 주세요.'};if(Object.entries(d.placements).some(([id,p])=>id!==st.id&&p.room==='counsel'&&p.status==='supporting'))return {error:'지원실의 담당 교사가 다른 학생을 지원 중입니다. 교실 지원과 관리자 협의를 이어 가세요.'};d.placements[st.id]={room:'counsel',assignee:'counselor',status:'supporting',start:s.minute,day:s.day,caseId:c.id,learning:text};c.assignee='counselor';c.response='학교 담당자 확인 후 학습 지원';}
 if(c.kind==='health'&&c.step===1){c.assignee='nurse';d.placements[st.id]={room:'health',assignee:'nurse',status:'supporting',start:s.minute,day:s.day,caseId:c.id};M.addMessage(s,'all','이보람 보건교사',st.name+' 학생을 인수했습니다. 확인 전에는 병명을 단정하지 않고 보호자와 필요한 안내를 확인하겠습니다.',{senderId:'nurse',recipientId:'teacher',plannerScanned:true});}
 if(c.kind==='health'&&c.step===2){c.health=choice===0?HEALTH_TOPICS[(s.config.seed+d.cases.indexOf(c))%8]:null;c.confirmedBy='가상 보호자·보건 담당자 확인';c.clearance=false;c.reportDay=s.day;d.placements[st.id]={...(d.placements[st.id]||{}),room:'home',status:'handed-off',guardian:st.parentId};(s.attendance[s.day]??={})[st.id]=c.health?'인정결석':'조퇴';d.handoffs.push({studentId:st.id,day:s.day,minute:s.minute,to:st.parentId,reason:'보건 담당자와 보호자 인계',date:M.stamp(s)});M.addMessage(s,'parent',st.name+' 보호자',c.health?'보건 담당자에게 확인 자료를 전달했습니다. 복귀 가능 여부를 확인한 후 다시 연락드리겠습니다.':'오늘 건강 상태를 확인하고 안전하게 인계받았습니다.',{senderId:st.parentId,threadPerson:st.parentId,recipientId:'teacher',plannerScanned:true});}
 if(c.kind==='health'&&c.step===3&&!c.clearance)return {error:'보호자·보건 담당자의 복귀 확인을 먼저 받아 주세요. 정해진 며칠만으로 자동 복귀시키지 않습니다.'};
 if(['violence','rights','welfare'].includes(c.kind)&&c.step===1){c.assignee=c.kind==='rights'?'headteacher':'counselor';M.addMessage(s,'all',c.kind==='rights'?'학교장':'학생 지원 담당자','지원 요청을 접수했습니다. 확인한 사실과 필요한 보호를 바탕으로 담당 절차를 진행하겠습니다. 담임은 지원과 수업 연결을 맡아 주세요.',{senderId:c.assignee,plannerScanned:true});}
 c.history.push({step:c.step,label:steps[c.step],choice,text,date:M.stamp(s)});c.step++;if(c.step>=steps.length){c.closed=true;c.closedAt=M.stamp(s);if(d.placements[st.id])d.placements[st.id].status='returned';if(c.kind==='health')(s.attendance[s.day]??={})[st.id]='출석';M.remember(s,st,'필요한 도움을 확인하고 다시 참여할 방법을 함께 정했다.',1);}M.log(s,st.name+' · '+KINDS[c.kind]+' · '+(c.closed?'후속 확인 완료':steps[Math.min(c.step,steps.length-1)]));return {ok:true};}
export function clearance(s,id){const c=data(s).cases.find(x=>x.id===id);if(!c||c.kind!=='health'||c.step!==3||s.day<=c.reportDay)return {error:'건강 안내 후 다른 등교일에 보호자와 보건 담당자의 복귀 확인을 요청해 주세요.'};c.clearance=true;c.clearanceAt=M.stamp(s);c.clearanceEvidence='보호자가 전달한 확인 자료와 보건 담당자의 복귀 안내';return {ok:true};}
export function sync(s){if(!s.academic)return;const d=data(s);for(const c of d.cases){if(c.kind==='disruption'&&!c.closed&&c.step===4&&d.placements[c.studentId]?.day<s.day){d.placements[c.studentId].status='returned';c.step=5;c.history.push({step:4,text:'담당 교사의 학습 지원을 마치고 다음 날 교실 복귀 후 점검',date:M.stamp(s)});}if(c.kind==='health'&&c.step===3&&!c.clearance&&s.day>c.reportDay)(s.attendance[s.day]??={})[c.studentId]=c.health?'인정결석':'질병결석';}
 for(const doc of d.documents)if(!doc.transferred&&s.students.some(st=>st.id===doc.studentId)&&['approved','reported','closed'].includes(doc.stage)&&doc.kind!=='absence'&&s.day>=doc.from&&s.day<=doc.to&&A.schoolDay(s))setAttendance(s,doc.studentId,s.day,'교외체험학습','승인된 교외체험학습 '+doc.id);
 for(const doc of d.documents){const elapsed=s.academic.calendar.filter(x=>x.school&&x.day>doc.to&&x.day<=s.day).length;doc.dueStatus=doc.kind==='absence'&&doc.stage==='received'&&elapsed>d.rules.absenceDays?'제출 기한 확인':doc.kind!=='absence'&&doc.stage==='approved'&&elapsed>d.rules.familyReportDays?'보고서 안내 필요':null;}const key=s.academic.year+'-'+Math.floor(s.day/20);if(s.academic.phase==='term'&&A.schoolDay(s)&&s.minute>=585&&!d.seen[key]&&!s.staffWork?.away){d.seen[key]=true;const st=s.students[(Math.floor(s.day/20)+s.config.seed)%s.students.length];if(M.isPresent(s,st.id))M.addMessage(s,'all','이보람 보건교사',st.name+' 학생이 몸 상태를 확인하고 싶다고 합니다. 필요한 경우 학생 지원창에 관찰 내용과 연락할 담당자를 기록해 주세요.',{senderId:'nurse',recipientId:'teacher',plannerScanned:true});}
}
export function setAttendance(s,studentId,day,value,reason){const d=data(s),old=s.attendance[day]?.[studentId]||'출석';if(old===value)return;(s.attendance[day]??={})[studentId]=value;d.attendanceChanges.push({studentId,day,from:old,to:value,reason,date:M.stamp(s)});}
export function submitDocument(s,input){const d=data(s),from=Number(input.from),to=Number(input.to),st=s.students.find(x=>x.id===input.studentId);if(!st||!['family','home','absence'].includes(input.kind)||!Number.isInteger(from)||!Number.isInteger(to)||to<from||from<s.academic.start||to>s.academic.end||!String(input.detail).trim())return {error:'학생·기간·신청 내용을 확인해 주세요.'};if(s.community&&!permitted(s,st.parentId,st.id,input.kind==='absence'?'messages':'consent'))return {error:'이 학생의 신청·연락 권한이 확인된 보호자 자료인지 먼저 확인해 주세요.'};const old=d.documents.find(x=>x.studentId===st.id&&x.kind===input.kind&&x.from===from&&x.to===to);if(old){old.channels=[...new Set([...old.channels,input.channel||'앱'])];if(old.stage==='revision'){old.detail=String(input.detail).slice(0,1000);old.evidence=String(input.evidence||'').slice(0,300);old.stage='received';}return {ok:true,id:old.id,duplicate:true};}const doc={id:'doc-'+s.academic.year+'-'+d.documents.length,studentId:st.id,kind:input.kind,from,to,detail:String(input.detail).slice(0,1000),evidence:String(input.evidence||'').slice(0,300),absenceType:['질병결석','기타결석','인정결석'].includes(input.absenceType)?input.absenceType:'질병결석',channels:[input.channel||'앱'],stage:'received',date:M.stamp(s),history:[]};d.documents.unshift(doc);return {ok:true,id:doc.id};}
export function documentAction(s,id,action,note){const d=data(s),f=d.documents.find(x=>x.id===id);if(!f)return false;if(f.transferred||!s.students.some(st=>st.id===f.studentId))return {error:'전출 학교로 인계된 서류입니다. 이 학교에서는 과거 기록만 열람합니다.'};const text=String(note||'').trim();if(text.length<4)return {error:'확인 근거나 보완할 내용을 적어 주세요.'};if(action==='revise'&&f.stage==='received')f.stage='revision';else if(action==='approve'&&f.stage==='received'){if(f.kind==='absence'&&f.to>s.day)return {error:'미래의 결석을 실제 출결로 확정할 수 없습니다.'};if(f.kind==='home'&&!d.rules.homeStudy)return {error:'이 학교의 현재 규칙은 가정학습을 허용하지 않습니다. 다른 신청 내용으로 보완해 주세요.'};if(f.kind!=='absence'&&s.academic.calendar.filter(x=>x.school&&x.day>s.day&&x.day<=f.from).length<d.rules.familyLeadDays)return {error:'가상 학교의 사전 신청 기한을 확인하고 보완 협의를 남겨 주세요.'};if(!f.evidence.trim())return {error:'확인 자료 또는 승인 근거를 먼저 입력해 주세요.'};f.stage=f.kind==='absence'?'closed':'approved';if(f.kind==='absence')for(let day=f.from;day<=Math.min(f.to,s.day);day++)if(A.schoolDay(s,day))setAttendance(s,f.studentId,day,f.absenceType,'결석계 확인 '+id);}else if(action==='report'&&f.stage==='approved'){if(s.day<=f.to)return {error:'실시 기간이 끝난 뒤 보고서를 받을 수 있습니다.'};f.stage='reported';f.report=text;}else if(action==='close'&&f.stage==='reported')f.stage='closed';else return {error:'서류의 현재 처리 단계를 확인해 주세요.'};f.history.push({action,text,date:M.stamp(s)});return {ok:true};}
export function valid(s){const d=s.support;if(d==null)return true;const ids=knownIds(s);return d.schema===1&&Array.isArray(d.cases)&&d.cases.length<=3000&&d.cases.every(c=>ids.has(c.studentId)&&KINDS[c.kind]&&Number.isInteger(c.step)&&c.step>=0&&c.step<=STEPS[c.kind].length&&Array.isArray(c.history)&&typeof c.closed==='boolean')&&d.placements&&Object.keys(d.placements).every(id=>ids.has(id))&&Array.isArray(d.documents)&&d.documents.every(f=>ids.has(f.studentId)&&['family','home','absence'].includes(f.kind)&&f.from<=f.to&&f.from>=s.academic.start&&f.to<=s.academic.end&&['received','revision','approved','reported','closed'].includes(f.stage))&&Array.isArray(d.attendanceChanges)&&Array.isArray(d.handoffs)&&d.seen&&d.rules;}
